### 2. Validación de Esquemas Zod (Cliente y Servidor)
Cualquier comando o búsqueda ejecutada desde el Omnibox debe validarse estrictamente mediante esquemas Zod compartidos para evitar inyecciones o estados inválidos en el multi-tenant.

```typescript
// src/schemas/omnibox.schema.ts
import { z } from 'zod';

export const omniboxQuerySchema = z.object({
  tenant_id: z.string().uuid(),
  query: z.string().min(1, "La consulta no puede estar vacía").max(100),
  context_filter: z.enum(['all', 'inventory', 'invoices', 'customers', 'dian']).default('all'),
  limit: z.number().int().min(1).max(50).default(10),
});

export const omniboxActionSchema = z.object({
  tenant_id: z.string().uuid(),
  action_type: z.enum(['QUICK_INVOICE', 'REGISTER_PAYMENT', 'VIEW_DIAN_STATUS', 'CHECK_STOCK']),
  payload: z.record(z.unknown()),
});

export type OmniboxQueryInput = z.infer<typeof omniboxQuerySchema>;
export type OmniboxActionInput = z.infer<typeof omniboxActionSchema>;
```

